def main():
    print(f"Generating vit_test.csv: {len(phishing_samples)} phishing, {len(legitimate_samples)} legitimate...")
    with open("data/vit_test.csv", "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["sender", "subject", "body", "label"])
        for row in phishing_samples:
            writer.writerow(row)
        for row in legitimate_samples:
            writer.writerow(row)
    print("Done! Total rows:", len(phishing_samples) + len(legitimate_samples))

if __name__ == "__main__":
    main()
